BEGIN;
-- Chave da loja criada no banco e armazenada no gerador apenas como hash.
do $$
declare
  v_slug constant text := 'lets';
  v_email constant text := 'letsoculosesportivos@gmail.com';
  v_phone constant text := '5581991913135';
  v_domain constant text := 'https://provoulevou.com.br/catalogo/?loja=lets';
  v_lead constant uuid := '5eebd8e5-dbad-452d-93d1-0d4983a51c9e';
  v_key text;
begin
  if exists (select 1 from public.pl_catalog_stores where slug=v_slug) then
    raise notice 'Catálogo já cadastrado: %',v_slug;
    return;
  end if;
  if exists (select 1 from public.pl_catalog_stores where lower(owner_email)=v_email) then
    raise exception 'Este e-mail já possui catálogo; revisar identidade antes de criar';
  end if;
  if not exists (select 1 from public.leads where id=v_lead and telefone='558193227426') then
    raise exception 'Lead da Lets não confirmado';
  end if;
  v_key := encode(gen_random_bytes(32),'hex');
  values (v_slug,'Let’s Óculos Esportivos','https://provoulevou.com.br/catalogo/assets/lets/logo.webp',v_phone,v_email,
    'basic',true,'#C53610',
    '{"bg":"#FFF8F4","card":"#FFFFFF","line":"#F0D6CA","brand":"#C53610","dark":"#9B290C","soft":"#FFE4D9","on":"#FFFFFF","cta":"#C53610","ctaDark":"#9B290C","onCta":"#FFFFFF"}'::jsonb,
    3,v_key);
  values ('Let’s Óculos Esportivos',v_domain,v_email,'Let’s Óculos Esportivos',v_phone,'basic','Teste Gratuito',true,
    encode(digest(v_key,'sha256'),'hex'),true,'catalogo','oculos',v_slug);
  update public.leads set status='testando',email=v_email,updated_at=now(),
    teste_gratis_em=coalesce(teste_gratis_em,current_date)
    where id=v_lead;
    on conflict (lead_id) do update set status=excluded.status,updated_at=now();
    select v_lead,'nota','Catálogo Lets criado; teste grátis de 7 dias iniciado.'
    where not exists (select 1 from public.interacoes where lead_id=v_lead and tipo='nota'
      and conteudo='Catálogo Lets criado; teste grátis de 7 dias iniciado.');
end $$;

























COMMIT;
